head.script:
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Sel);

        // 호출파라미터설정
        scwin.setParam();

        // 파일구분 수정항목 조회
        const dsNm = 'BNS_FILE_APPL_LIST';
        const qryId = 'lds.stf.bnslistbzappl.select.readFileConnModAttachFileTpCd';
        let param;
        param += '&{P}V_ISUR_CD=' + scwin.objParam.ISUR_CD;
        param += '&{P}V_APPL_DD=' + scwin.objParam.APPL_DD_TM.substring(0, 8);
        param += '&{P}V_APPL_TM=' + scwin.objParam.APPL_DD_TM.substring(8, 14);
        $c.bns.fn_SearchBns('ULDBNS20501.xml', dts_DtlInfo, dsNm, qryId, param);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20501.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20501.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「파일구분수정」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Mod_onclick = function() {
    try {
        if (dts_DtlInfo.getRowCount() === 0) return;
        scwin.update();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20501.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name trs_Update_OnSuccess
 * @description Update On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnSuccess = async function() {
    try {
        let arrPar = new Array();
        arrPar[0] = {
            MOD_YN: 'Y'
        };
        const parentFrame = $c.frame.path("../");
        scwin.fn_SetPar = parentFrame.fn_SetModAttachFileTpCd;
        scwin.fn_SetPar(arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20501.trs_Update_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Update_OnFail
 * @description Update On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20501.trs_Update_OnFail" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20501.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.ISUR_CD = arrPar[0].ISUR_CD;
        scwin.objParam.APPL_DD_TM = arrPar[0].APPL_DD_TM;
    }
};

/**
 * @method
 * @name update
 * @description 파일구분 수정
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    if (dts_DtlInfo.getRowCount() === 0) return;
    let url = '/bns/FileFaxConn.do?method=updateAttachFileTpCd';
    url += '&SCREN_ID=' + 'ULDBNS20501.xml';
    url += '&SCREN_PROCES_TP_CD=' + SCREN_PROCS_TP_CD_03;
    url += '&ATTACH_FILE_TP_CD=' + rdo_AttachFileTpCd.getValue();
    url += '&ISUR_CD=' + scwin.objParam.ISUR_CD;
    url += '&APPL_DD=' + scwin.objParam.APPL_DD_TM.substring(0, 8);
    url += '&APPL_TM=' + scwin.objParam.APPL_DD_TM.substring(8, 14);
    url += '&FILE_FAX=' + 'FILE';
    trs_Update.Action = $c.lc.fn_encodeNSession(url);
    trs_Update.KeyName = "toinb_dataid4";
    trs_Update.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Update.Post();
};
